INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'interior','done','Klassik hovli-uy','Классический дом','Interyer dizayn','Дизайн интерьера','Ikki qavatli hovli-uy interyeri klassik uslubda — katta kirish zali, asosiy yotoqxona, hashamatli detallar va tabiiy materiallar. Loyihada har bir xona uchun yagona uslub, yorug''lik ssenariysi va mebel joylashuvi ishlab chiqildi. Bu loyiha amalga oshirilgan va obyekt topshirilgan.','Интерьер двухэтажного дома в классическом стиле — просторный холл, главная спальня, изысканные детали и натуральные материалы. Для каждого помещения разработаны единая стилистика, сценарии освещения и расстановка мебели. Проект реализован, объект сдан.','assets/int-10-sm.webp','assets/int-10.webp','["assets/int-11.webp", "assets/int-12.webp", "assets/int-13.webp"]',0,'klassik-hovli-uy','классический-дом','Klassik','Классика' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='klassik-hovli-uy');
INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'interior','render','Klassik oshxona va mehmonxona','Классическая кухня-гостиная','Interyer dizayn','Дизайн интерьера','Ochiq oshxona va mehmonxona zonalari — nozik gips detallari, marmar va nafis mebel. Ikki zona yagona kompozitsiyada birlashtirilib, oilaviy yig''ilishlar uchun keng va yorug'' makon yaratildi. Loyiha 3D vizualizatsiya bosqichida taqdim etilgan.','Открытая кухня и гостиная — тонкая лепнина, мрамор и изысканная мебель. Две зоны объединены в единую композицию, создавая просторное и светлое пространство для семейных встреч. Проект представлен на этапе 3D-визуализации.','assets/about-office-sm.webp','assets/about-office.webp','["assets/int-03.webp", "assets/int-08.webp", "assets/int-09.webp"]',1,'klassik-oshxona-va-mehmonxona','классическая-кухня-гостиная','Klassik','Классика' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='klassik-oshxona-va-mehmonxona');
INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'interior','render','Zamonaviy kvartira','Современная квартира','Interyer dizayn','Дизайн интерьера','Zamonaviy uslubdagi kvartira — ochiq planirovka, neytral ranglar, garderob xonasi va funksional oshxona. Kundalik qulaylik uchun saqlash tizimlari va yoritish puxta o''ylangan. Loyiha 3D vizualizatsiya bosqichida taqdim etilgan.','Квартира в современном стиле — открытая планировка, нейтральные тона, гардеробная и функциональная кухня. Системы хранения и освещение продуманы для повседневного комфорта. Проект представлен на этапе 3D-визуализации.','assets/int-02-sm.webp','assets/int-02.webp','["assets/int-01.webp", "assets/hero.webp", "assets/int-06.webp"]',2,'zamonaviy-kvartira','современная-квартира','Zamonaviy','Современный' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='zamonaviy-kvartira');
INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'interior','render','Klassik dahliz va yotoqxona','Классический холл и спальня','Interyer dizayn','Дизайн интерьера','Klassik dahliz, marmar pol va ikki karavotli yotoqxona — oq va bej tonlarda hashamatli yechim. Nozik dekor va yumshoq yoritish xonalarga osoyishta muhit bag''ishlaydi. Loyiha 3D vizualizatsiya bosqichida taqdim etilgan.','Классический холл с мраморным полом и спальня с двумя кроватями — изысканное решение в белых и бежевых тонах. Деликатный декор и мягкий свет создают спокойную атмосферу. Проект представлен на этапе 3D-визуализации.','assets/int-04-sm.webp','assets/int-04.webp','["assets/int-05.webp", "assets/int-07.webp"]',3,'klassik-dahliz-va-yotoqxona','классический-холл-и-спальня','Klassik','Классика' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='klassik-dahliz-va-yotoqxona');
INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'architecture','render','Klassik villa fasadi','Фасад классической виллы','Arxitektura','Архитектура','Klassik uslubdagi shaxsiy villa fasadi — mansard tomi, dekorativ pilyastralar va nozik gips detallari. Fasad proporsiyalari va bezaklari binoning umumiy arxitekturasi bilan uyg''un ishlab chiqildi. Loyiha 3D vizualizatsiya bosqichida taqdim etilgan.','Фасад частной виллы в классическом стиле — мансардная крыша, декоративные пилястры и тонкая лепнина. Пропорции и декор фасада разработаны в гармонии с общей архитектурой здания. Проект представлен на этапе 3D-визуализации.','assets/arch-01-sm.webp','assets/arch-01.webp','["assets/arch-02.webp", "assets/arch-03.webp", "assets/arch-04.webp", "assets/arch-05.webp"]',4,'klassik-villa-fasadi','фасад-классической-виллы','Klassik','Классика' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='klassik-villa-fasadi');
INSERT INTO projects (category,status,title_uz,title_ru,type_uz,type_ru,desc_uz,desc_ru,thumb_url,hero_url,gallery_urls,sort_order,slug,slug_ru,style_uz,style_ru) SELECT 'drawings','done','Ishchi chizmalar to''plami','Комплект рабочих чертежей','Chizmalar','Чертежи','Elektrika, devor rejasi, shift konstruksiyasi, yoritish va mebel joylashuvi bo''yicha to''liq ishchi chizmalar. Ustalar ishni loyihaga aniq mos bajarishi uchun har bir chizmada o''lcham va belgilar batafsil ko''rsatilgan.','Полный комплект рабочих чертежей: электрика, перегородки, потолки, освещение, расстановка мебели. Каждый лист содержит подробные размеры и обозначения, чтобы мастера выполнили работы точно по проекту.','assets/draw-01-sm.webp','assets/draw-01.webp','["assets/draw-02.webp", "assets/draw-03.webp", "assets/draw-04.webp", "assets/draw-05.webp"]',5,'ishchi-chizmalar-toplami','комплект-рабочих-чертежей','','' WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='ishchi-chizmalar-toplami');
